exception Invalid_config of string

let parse_port s =
  match int_of_string_opt s with
  | None -> raise (Invalid_config ("not a number: " ^ s))
  | Some p when p < 1 || p > 65535 -> raise (Invalid_config ("out of range: " ^ s))
  | Some p -> p

let with_context ctx f =
  try f () with Invalid_config m -> raise (Invalid_config (ctx ^ ": " ^ m))

let () =
  Printf.printf "%d\n" (parse_port "8080");
  (try ignore (parse_port "x") with Invalid_config m -> print_endline m);
  (try ignore (with_context "server" (fun () -> parse_port "99999")) with Invalid_config m -> print_endline m);
  (match int_of_string "q" with
   | n -> Printf.printf "parsed %d\n" n
   | exception Failure _ -> print_endline "not an int");
  match int_of_string "7" with
  | n -> Printf.printf "parsed %d\n" n
  | exception Failure _ -> print_endline "not an int"

let rec map f = function [] -> [] | x :: xs -> let y = f x in y :: map f xs
let rec filter p = function [] -> [] | x :: xs -> if p x then x :: filter p xs else filter p xs
let map_tr f l = List.rev (List.fold_left (fun acc x -> f x :: acc) [] l)

type 'a tree = Leaf | Node of 'a tree * 'a * 'a tree

let rec map_tree f = function
