  | Node (l, v, r) -> Node (map_tree f l, f v, map_tree f r)

let rec to_list = function Leaf -> [] | Node (l, v, r) -> to_list l @ [ v ] @ to_list r
let opt_map f = function None -> None | Some x -> Some (f x)

