let f x = x * 2
let g x = x + 1
let even x = x mod 2 = 0
let positive x = x > 0

let () =
  holds "map composes" (fun l -> List.map f (List.map g l) = List.map (fun x -> f (g x)) l);
  holds "map id" (fun l -> List.map Fun.id l = l);
  holds "filters commute" (fun l -> List.filter even (List.filter positive l) = List.filter positive (List.filter even l));
  holds "fold cons rebuilds" (fun l -> List.fold_right (fun x acc -> x :: acc) l [] = l);
  holds "map keeps length" (fun l -> List.length (List.map f l) = List.length l);
  holds "a false law" (fun l -> List.map g (List.rev l) = l)

